		{"cell", func(e *FunctionExpectation) { e.Cell = "FRA" }},
		{"stale-sequence", func(e *FunctionExpectation) { e.MinimumSequence++ }},
		{"missing-floor", func(e *FunctionExpectation) { e.MinimumSequence = 0 }},
	} {
