func productionCandidate(binary binaryReceipt, cell string) release.ProductionExpectation {
	return release.ProductionExpectation{SourceRevision: binary.SourceRevision, ArtifactSHA256: binary.SHA256,
		QualificationSHA256: binary.QualificationSHA256, Cell: cell, Environment: "production",
		Runtime: release.ProductionRuntime, Architecture: binary.GOARCH, Role: "orchestrator"}
}

func writeProductionEvidence(t *testing.T, directory string, candidate release.ProductionExpectation) release.ProductionQualification {
	t.Helper()
	if err := os.MkdirAll(filepath.Join(directory, "objects"), 0o700); err != nil {
		t.Fatal(err)
	}
	record := release.ProductionQualification{Schema: release.ProductionQualificationSchema, Candidate: candidate}
	for _, gate := range []string{"runtime-ha", "workload-safety"} {
		data, err := json.Marshal(struct{ Gate, SourceRevision, ArtifactSHA256 string }{gate, candidate.SourceRevision, candidate.ArtifactSHA256})
		if err != nil {
			t.Fatal(err)
		}
		digest := sha256.Sum256(data)
		sum := hex.EncodeToString(digest[:])
		if err := os.WriteFile(filepath.Join(directory, "objects", sum), data, 0o600); err != nil {
			t.Fatal(err)
		}
		record.Evidence = append(record.Evidence, release.ProductionGateEvidence{Gate: gate, SHA256: sum,
			Bytes: int64(len(data)), CompletedAt: time.Now().UTC().Add(-3 * time.Hour)})
	}
	return record
}

func writeProductionRecord(t *testing.T, path string, record release.ProductionQualification, private ed25519.PrivateKey, issued, expires time.Time) {
	t.Helper()
	payload, err := trust.EncodePayload(record)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := trust.Sign(payload, release.ProductionQualificationScope(record.Candidate), issued, expires, private)
	if err != nil {
		t.Fatal(err)
	}
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(path, wire, 0o600); err != nil {
		t.Fatal(err)
	}
}

func (c command) verifyProductionArtifacts(evidenceDir string, roots trust.Keyring, cell, environment string, binaries map[string]binaryReceipt, now time.Time) error {
	if len(binaries) == 0 {
		return fmt.Errorf("%w: no candidate artifacts", release.ErrProductionQualification)
	}
	for architecture, binary := range binaries {
		if err := binary.Validate(); err != nil {
			return fmt.Errorf("%w: %w", release.ErrProductionQualification, err)
		}
		if binary.GOARCH != architecture {
			return fmt.Errorf("%w: artifact architecture", release.ErrProductionQualification)
		}
		expected := release.ProductionExpectation{SourceRevision: binary.SourceRevision, ArtifactSHA256: binary.SHA256,
			QualificationSHA256: binary.QualificationSHA256, Cell: cell, Environment: environment,
			Runtime: release.ProductionRuntime, Architecture: architecture, Role: "orchestrator"}
		if err := c.verifyProductionCandidate(evidenceDir, roots, expected, now); err != nil {
			return err
		}
	}
	return c.ctx.Err()
}

// verifyProductionCandidate consumes only signed qualification and retained bytes.
func (c command) verifyProductionCandidate(evidenceDir string, roots trust.Keyring, expected release.ProductionExpectation, now time.Time) error {
	directory := filepath.Join(evidenceDir, expected.Cell, expected.Architecture)
	wire, err := readBoundedRegular(filepath.Join(directory, "production.json"), trust.MaxEnvelopeBytes)
	if err != nil {
		return fmt.Errorf("%w: %s %s record: %w", release.ErrProductionQualification, expected.Cell, expected.Architecture, err)
	}
	delegation, err := readBoundedRegular(filepath.Join(directory, "delegation.json"), trust.MaxEnvelopeBytes)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return fmt.Errorf("%w: qualification delegation: %w", release.ErrProductionQualification, err)
	}
	if _, err := release.VerifyProductionCurrent(wire, delegation, roots, expected, time.Now().UTC()); err != nil {
		return fmt.Errorf("%s %s current admission: %w", expected.Cell, expected.Architecture, err)
	}
	qualification, err := release.VerifyProductionCurrent(wire, delegation, roots, expected, now)
	if err != nil {
		return fmt.Errorf("%s %s: %w", expected.Cell, expected.Architecture, err)
	}
	for _, evidence := range qualification.Evidence {
		file, err := openRegular(filepath.Join(evidenceDir, "objects", evidence.SHA256))
		if err != nil {
			return fmt.Errorf("%w: %s %s evidence: %w", release.ErrProductionQualification, expected.Cell, evidence.Gate, err)
		}
		if err := errors.Join(release.VerifyProductionEvidence(c.ctx, file, evidence, expected), file.Close()); err != nil {
			return fmt.Errorf("%s %s retained evidence: %w", expected.Cell, evidence.Gate, err)
		}
	}
	return c.ctx.Err()
}

func readProductionProof(evidenceDir, cell, architecture string) (release.ProductionProof, error) {
	directory := filepath.Join(evidenceDir, cell, architecture)
	wire, err := readBoundedRegular(filepath.Join(directory, "production.json"), trust.MaxEnvelopeBytes)
	if err != nil {
		return release.ProductionProof{}, err
	}
	delegation, err := readBoundedRegular(filepath.Join(directory, "delegation.json"), trust.MaxEnvelopeBytes)
	if err != nil && !errors.Is(err, os.ErrNotExist) {
		return release.ProductionProof{}, err
	}
	return release.ProductionProof{Qualification: wire, Delegation: delegation}, nil
}

func VerifyProductionEvidence(ctx context.Context, reader io.Reader, evidence ProductionGateEvidence, expected ProductionExpectation) error {
	if err := ctx.Err(); err != nil {
		return err
	}
	if reader == nil || evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || !digestPattern.MatchString(evidence.SHA256) {
		return fmt.Errorf("%w: retained %s evidence metadata", ErrProductionQualification, evidence.Gate)
	}
	digest := sha256.New()
	var body bytes.Buffer
	var destination io.Writer = digest
	if evidence.Gate == RootCredentialBoundaryGate {
		destination = io.MultiWriter(digest, &body)
	}
	count, err := io.Copy(destination, io.LimitReader(reader, evidence.Bytes+1))
	if err != nil {
		return fmt.Errorf("read retained %s evidence: %w", evidence.Gate, err)
	}
	if count != evidence.Bytes || hex.EncodeToString(digest.Sum(nil)) != evidence.SHA256 {
		return fmt.Errorf("%w: retained %s evidence differs from the signed size or SHA-256", ErrProductionQualification, evidence.Gate)
	}
	if evidence.Gate == RootCredentialBoundaryGate {
		var boundary RootCredentialBoundaryEvidence
		if err := protocol.DecodeStrict(body.Bytes(), &boundary, MaxProductionEvidenceBytes); err != nil {
			return fmt.Errorf("%w: root credential boundary evidence: %w", ErrProductionQualification, err)
		}
		if err := boundary.Validate(expected); err != nil {
			return err
		}
		if !boundary.CompletedAt.Equal(evidence.CompletedAt) {
			return fmt.Errorf("%w: root credential boundary completion time", ErrProductionQualification)
		}
	}
	return ctx.Err()
}

// Validate checks the delegation's subject key and scope lists.
func (delegation BinaryUpdateDelegation) Validate() error {
	if delegation.Schema != UpdateDelegationSchema || !ValidEnvironment(delegation.Environment) ||
		delegation.Repository != QualificationRepository || delegation.Workflow != QualificationWorkflow ||
		delegation.Ref != LineageRef || !revisionPattern.MatchString(delegation.LineageBase) ||
		len(delegation.Architectures) == 0 || len(delegation.Architectures) > 2 || len(delegation.Services) > maxUpdateDelegationServices {
		return fmt.Errorf("%w: binary update delegation scope", ErrInvalidReceipt)
	}
	if !sortedUnique(delegation.Architectures, func(value string) bool { return value == "amd64" || value == "arm64" }) {
		return fmt.Errorf("%w: binary update delegation architectures", ErrInvalidReceipt)
	}
	if err := validateServiceGrants(delegation.Services); err != nil {
		return err
	}
	publicKey, err := base64.RawURLEncoding.DecodeString(delegation.SubjectPublicKey)
	if err != nil || len(publicKey) != ed25519.PublicKeySize {
		return fmt.Errorf("%w: delegated public key", ErrInvalidReceipt)
	}
	keyID, err := trust.KeyID(ed25519.PublicKey(publicKey))
	if err != nil || keyID != delegation.SubjectKeyID {
		return trust.ErrKeyMismatch
	}
	return nil
}

func sortedUnique(values []string, valid func(string) bool) bool {
	for index, value := range values {
		if !valid(value) || index > 0 && values[index-1] >= value {
			return false
		}
	}
	return true
}

// validateServiceGrants requires grants sorted by strictly ascending role, so each role appears once.
func validateServiceGrants(services []ServiceGrant) error {
	for index, service := range services {
		repository, err := url.Parse(service.Repository)
		if !serviceRolePattern.MatchString(service.Role) || index > 0 && services[index-1].Role >= service.Role ||
			err != nil || repository.Scheme != "https" || repository.Host == "" || len(service.Repository) > 512 {
			return fmt.Errorf("%w: binary update delegation services", ErrInvalidReceipt)
		}
	}
	return nil
}

// MayRelease reports whether the delegation names exactly this role and repository.
func (delegation BinaryUpdateDelegation) MayRelease(role, repository string) bool {
	return slices.Contains(delegation.Services, ServiceGrant{Role: role, Repository: repository})
}

// Validate checks the receipt payload's own fields.
func (receipt BinaryUpdateReceipt) Validate() error {
	if (receipt.ReleaseSequence == 0) != (receipt.SequenceMigrationSHA256 == "") || receipt.SequenceMigrationSHA256 != "" && !digestPattern.MatchString(receipt.SequenceMigrationSHA256) {
		return fmt.Errorf("%w: release order", ErrInvalidReceipt)
	}
	if receipt.Schema != UpdateReceiptSchema || !ValidRegion(receipt.Cell) || !digestPattern.MatchString(receipt.DelegationSHA256) ||
		receipt.Lineage.Repository != QualificationRepository || receipt.Lineage.Workflow != QualificationWorkflow ||
		receipt.Lineage.Ref != LineageRef || !revisionPattern.MatchString(receipt.Lineage.LineageBase) ||
		receipt.Lineage.QualificationRunID <= 0 || receipt.Lineage.QualificationRunNum <= 0 {
		return fmt.Errorf("%w: binary update receipt scope or lineage", ErrInvalidReceipt)
	}
	return receipt.Binary.Validate()
}

// UpdateDelegationScope is the root signature scope of a delegation for one
// environment.
func UpdateDelegationScope(environment string) trust.Scope {
	return trust.Scope{
		Domain: UpdateDelegationDomain, DeploymentID: updateDelegationDeployment, Cell: updateDelegationCell,
		Environment: environment, Role: updateDelegationRole, Slot: updateDelegationSlot,
	}
}

// UpdateReceiptScope is the leaf signature scope of one update receipt.
func UpdateReceiptScope(receipt BinaryUpdateReceipt, environment string) trust.Scope {
	return trust.Scope{
		Domain: UpdateReceiptDomain, DeploymentID: entityid.Derive("build", receipt.Binary.SourceRevision), Cell: receipt.Cell,
		Environment: environment, Role: "artifact", Slot: "linux-" + receipt.Binary.GOARCH,
	}
}

// SignUpdateDelegation is the offline root operation that issues a grant.
func SignUpdateDelegation(delegation BinaryUpdateDelegation, issuedAt, expiresAt time.Time,
	rootPrivateKey ed25519.PrivateKey,
) (trust.Envelope, error) {
	if err := delegation.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if !expiresAt.After(issuedAt) || expiresAt.Sub(issuedAt) > MaxUpdateDelegationLifetime {
		return trust.Envelope{}, fmt.Errorf("binary update delegation must expire within %s", MaxUpdateDelegationLifetime)
	}
	payload, err := trust.EncodePayload(delegation)
	if err != nil {
		return trust.Envelope{}, err
	}
	return trust.Sign(payload, UpdateDelegationScope(delegation.Environment), issuedAt, expiresAt, rootPrivateKey)
}

type verifiedUpdateDelegation struct {
	delegation BinaryUpdateDelegation
	envelope   trust.Envelope
	digest     string
	publicKey  ed25519.PublicKey
}

// envelopeCheck is trust.VerifyHistorical or, through currentAt, trust.VerifyCurrent.
type envelopeCheck func(trust.Envelope, trust.Scope, trust.Keyring, trust.Policy) ([]byte, error)

func currentAt(now time.Time) envelopeCheck {
	return func(envelope trust.Envelope, scope trust.Scope, keys trust.Keyring, policy trust.Policy) ([]byte, error) {
		return trust.VerifyCurrent(envelope, scope, keys, now, policy)
	}
}

func verifyUpdateDelegation(envelope trust.Envelope, roots trust.Keyring, environment string,
	check envelopeCheck,
) (verifiedUpdateDelegation, error) {
	payload, err := check(envelope, UpdateDelegationScope(environment), roots,
		trust.Policy{MaxLifetime: MaxUpdateDelegationLifetime, ClockSkew: clockSkew})
	if err != nil {
		return verifiedUpdateDelegation{}, fmt.Errorf("verify binary update delegation: %w", err)
	}
	delegation, err := decodeCanonicalPayload[BinaryUpdateDelegation](payload)
	if err != nil {
		return verifiedUpdateDelegation{}, err
	}
	if err := delegation.Validate(); err != nil {
		return verifiedUpdateDelegation{}, err
	}
	if delegation.Environment != environment {
		return verifiedUpdateDelegation{}, ErrExpectationMismatch
	}
	digest, err := trust.Fingerprint(envelope)
	if err != nil {
		return verifiedUpdateDelegation{}, err
	}
	publicKey, _ := base64.RawURLEncoding.DecodeString(delegation.SubjectPublicKey)
	return verifiedUpdateDelegation{delegation: delegation, envelope: envelope, digest: digest, publicKey: publicKey}, nil
}

func (verified verifiedUpdateDelegation) authorize(receipt BinaryUpdateReceipt) error {
	delegation := verified.delegation
	if !slices.Contains(delegation.Architectures, receipt.Binary.GOARCH) {
		return fmt.Errorf("%w: architecture is outside the delegation", trust.ErrCapabilityDenied)
	}
	if receipt.DelegationSHA256 != verified.digest || receipt.Lineage.Repository != delegation.Repository ||
		receipt.Lineage.Workflow != delegation.Workflow || receipt.Lineage.Ref != delegation.Ref ||
		receipt.Lineage.LineageBase != delegation.LineageBase {
		return ErrLineage
	}
	return nil

func SignBinaryUpdateReceipt(binary BinaryReceipt, qualification Qualification, qualificationSHA256, cell, environment string,
	checker LineageChecker, delegationEnvelope trust.Envelope, roots trust.Keyring, privateKey ed25519.PrivateKey,
	now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	return signBinaryUpdateReceipt(binary, qualification, qualificationSHA256, cell, environment, checker, delegationEnvelope, roots, privateKey, now, validFor, 0, "")
}

// SignBinaryUpdateReceiptSequenced binds the signer-owned order and its exact
// root-authorized migration without changing historical CI provenance.
func SignBinaryUpdateReceiptSequenced(binary BinaryReceipt, qualification Qualification, qualificationSHA256, cell, environment string,
	checker LineageChecker, delegationEnvelope trust.Envelope, roots trust.Keyring, privateKey ed25519.PrivateKey,
	now time.Time, validFor time.Duration, sequence uint64, migrationSHA256 string,
) (trust.Envelope, error) {
	if sequence == 0 || !digestPattern.MatchString(migrationSHA256) {
		return trust.Envelope{}, fmt.Errorf("%w: release order", ErrInvalidReceipt)
	}
	return signBinaryUpdateReceipt(binary, qualification, qualificationSHA256, cell, environment, checker, delegationEnvelope, roots, privateKey, now, validFor, sequence, migrationSHA256)
}

func signBinaryUpdateReceipt(binary BinaryReceipt, qualification Qualification, qualificationSHA256, cell, environment string,
	checker LineageChecker, delegationEnvelope trust.Envelope, roots trust.Keyring, privateKey ed25519.PrivateKey,
	now time.Time, validFor time.Duration, sequence uint64, migrationSHA256 string,
) (trust.Envelope, error) {
	if checker == nil {
		return trust.Envelope{}, fmt.Errorf("%w: no lineage checker", ErrLineage)
	}
	if validFor <= 0 || validFor > MaxUpdateReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("update receipt validity must be positive and no longer than %s", MaxUpdateReceiptLifetime)
	}
	if err := qualification.MatchBinary(binary, qualificationSHA256); err != nil {
		return trust.Envelope{}, err
	}
	verified, err := verifyUpdateDelegation(delegationEnvelope, roots, environment, currentAt(now))
	if err != nil {
		return trust.Envelope{}, err
	}
	if len(privateKey) != ed25519.PrivateKeySize {
		return trust.Envelope{}, trust.ErrKeyMismatch
	}
	signerKeyID, err := trust.KeyID(privateKey.Public().(ed25519.PublicKey))
	if err != nil || signerKeyID != verified.delegation.SubjectKeyID {
		return trust.Envelope{}, trust.ErrKeyMismatch
	}
	if err := checker.CheckLineage(verified.delegation.LineageBase, binary.SourceRevision, verified.delegation.Ref); err != nil {
		return trust.Envelope{}, fmt.Errorf("%w: %w", ErrLineage, err)
	}
	receipt := BinaryUpdateReceipt{
		Schema: UpdateReceiptSchema, Binary: binary, Cell: cell, DelegationSHA256: verified.digest,
		ReleaseSequence: sequence, SequenceMigrationSHA256: migrationSHA256,
		Lineage: SourceLineage{
			Repository: qualification.Repository, Workflow: qualification.Verification.Workflow, Ref: verified.delegation.Ref,
			LineageBase: verified.delegation.LineageBase, QualificationRunID: qualification.Verification.RunID,
			QualificationRunNum: qualification.Verification.RunNumber,
		},
	}
	if err := receipt.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if err := verified.authorize(receipt); err != nil {
		return trust.Envelope{}, err
	}
	expiresAt := now.Add(validFor)
	if delegationEnvelope.ExpiresAt.Before(expiresAt) {
		// The receipt is capped at its delegation's expiry. Refuse a cap
		// that would leave a receipt consumers reject almost at once.
		if remaining := delegationEnvelope.ExpiresAt.Sub(now); remaining < min(validFor, MinUpdateReceiptValidity) {
			return trust.Envelope{}, fmt.Errorf("update delegation expires in %s, less than the %s minimum receipt validity; renew the delegation",
				remaining.Round(time.Second), min(validFor, MinUpdateReceiptValidity))
		}
		expiresAt = delegationEnvelope.ExpiresAt
	}
	payload, err := trust.EncodePayload(receipt)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelope, err := trust.Sign(payload, UpdateReceiptScope(receipt, environment), now, expiresAt, privateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelopeWire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return trust.Envelope{}, err
	}
	delegationWire, err := trust.EncodeEnvelope(delegationEnvelope)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := VerifyBinaryUpdateCurrent(envelopeWire, delegationWire, roots,
		UpdateExpectation{Environment: environment, Cell: cell, Architecture: binary.GOARCH}, now); err != nil {
		return trust.Envelope{}, fmt.Errorf("signed update receipt fails consumer verification: %w", err)
	}
	return envelope, nil
}

// MinUpdateReceiptValidity is the shortest validity an update receipt is
// signed with when its delegation's expiry caps the requested validity.
const MinUpdateReceiptValidity = time.Hour

// VerifyBinaryUpdateCurrent verifies an automatically signed update receipt
// against a currently valid root delegation, the consumer's environment,
// cell and architecture, and the delegation's pinned lineage. It returns the
// same VerifiedBinary type as the per-source path.
func VerifyBinaryUpdateCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected UpdateExpectation, now time.Time,
) (VerifiedBinary, error) {
	receipt, proof, err := verifyBinaryUpdate(envelopeWire, delegationWire, roots, expected, currentAt(now))
	if err != nil {
		return VerifiedBinary{}, err
	}
	return VerifiedBinary{receipt: receipt, proof: proof}, nil
}

// VerifyReleaseDelegationCurrent verifies the root-signed update delegation for
// the consumer's environment against a currently valid root. It returns the
// delegation, the leaf key it authorizes and when the grant expires.
func VerifyReleaseDelegationCurrent(delegationWire []byte, roots trust.Keyring, environment string, now time.Time,
) (BinaryUpdateDelegation, ed25519.PublicKey, time.Time, error) {
	envelope, err := trust.DecodeEnvelope(delegationWire)
	if err != nil {
		return BinaryUpdateDelegation{}, nil, time.Time{}, err
	}
	verified, err := verifyUpdateDelegation(envelope, roots, environment, currentAt(now))
	if err != nil {
		return BinaryUpdateDelegation{}, nil, time.Time{}, err
	}
	return verified.delegation, verified.publicKey, envelope.ExpiresAt, nil
}

// VerifyBinaryUpdateHistorical verifies that an update receipt was signed
// within its root delegation for the consumer's environment, cell and
// architecture, without requiring either to be valid now. It proves the
// identity of a binary staged earlier under a current receipt; it never
// authorizes staging.
func VerifyBinaryUpdateHistorical(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected UpdateExpectation,
) (HistoricalBinary, error) {
	receipt, proof, err := verifyBinaryUpdate(envelopeWire, delegationWire, roots, expected, trust.VerifyHistorical)
	if err != nil {
		return HistoricalBinary{}, err
	}
	return HistoricalBinary{receipt: receipt, proof: proof}, nil
}

func verifyBinaryUpdate(envelopeWire, delegationWire []byte, roots trust.Keyring, expected UpdateExpectation,
	check envelopeCheck,
) (BinaryReceipt, receiptProof, error) {
	if err := validateEnvironment(expected.Environment); err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if !ValidRegion(expected.Cell) || expected.Architecture != "amd64" && expected.Architecture != "arm64" {
		return BinaryReceipt{}, receiptProof{}, fmt.Errorf("%w: update expectation", ErrExpectationMismatch)
	}
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	verified, err := verifyUpdateDelegation(delegationEnvelope, roots, expected.Environment, check)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	receipt, err := decodeCanonicalPayload[BinaryUpdateReceipt](envelope.Payload)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if err := receipt.Validate(); err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if receipt.Cell != expected.Cell || receipt.Binary.GOARCH != expected.Architecture {
		return BinaryReceipt{}, receiptProof{}, ErrExpectationMismatch
	}
	if err := verified.authorize(receipt); err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	if envelope.IssuedAt.Before(delegationEnvelope.IssuedAt) || envelope.ExpiresAt.After(delegationEnvelope.ExpiresAt) {
		return BinaryReceipt{}, receiptProof{}, trust.ErrDelegationTime
	}
	if _, err := check(envelope, UpdateReceiptScope(receipt, expected.Environment),
		trust.Keyring{verified.delegation.SubjectKeyID: verified.publicKey},
		trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime, ClockSkew: clockSkew}); err != nil {
		return BinaryReceipt{}, receiptProof{}, fmt.Errorf("verify binary update receipt: %w", err)
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return BinaryReceipt{}, receiptProof{}, err
	}
	return receipt.Binary, proof, nil
}

func productionBinaryExpectation(binary BinaryReceipt, expected UpdateExpectation) ProductionExpectation {
	return ProductionExpectation{SourceRevision: binary.SourceRevision, ArtifactSHA256: binary.SHA256,
		QualificationSHA256: binary.QualificationSHA256, Cell: expected.Cell, Environment: expected.Environment,
		Runtime: ProductionRuntime, Architecture: expected.Architecture, Role: "orchestrator"}
}

// VerifyQualifiedBinaryUpdateCurrent requires both release and qualification
// authority at the consumer's current time and own target scope.
func VerifyQualifiedBinaryUpdateCurrent(wire, delegationWire []byte, roots trust.Keyring, expected UpdateExpectation, now time.Time) (VerifiedBinary, error) {
	binary, err := VerifyBinaryUpdateCurrent(wire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedBinary{}, err
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return VerifiedBinary{}, err
	}
	var receipt BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return VerifiedBinary{}, err
	}
	if receipt.Production == nil {
		return VerifiedBinary{}, fmt.Errorf("%w: signed update contains no independent qualification", ErrProductionQualification)
	}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots,
		productionBinaryExpectation(binary.Receipt(), expected), now); err != nil {
		return VerifiedBinary{}, err
	}
	qualification, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return VerifiedBinary{}, err
	}
	if qualification.ExpiresAt.Before(binary.proof.expiresAt) {
		binary.proof.expiresAt = qualification.ExpiresAt
	}
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return VerifiedBinary{}, err
		}
		if delegation.ExpiresAt.Before(binary.proof.expiresAt) {
			binary.proof.expiresAt = delegation.ExpiresAt
		}
	}
	return binary, nil
}

// AttachProductionQualification preserves source/run provenance and signs the
// independent authority's exact candidate proof into the update receipt.
func AttachProductionQualification(envelope trust.Envelope, proof ProductionProof, delegationWire []byte, roots trust.Keyring, private ed25519.PrivateKey, expected UpdateExpectation, now time.Time) (trust.Envelope, error) {
	wire, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		return trust.Envelope{}, err
	}
	binary, err := VerifyBinaryUpdateCurrent(wire, delegationWire, roots, expected, now)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := VerifyProductionCurrent(proof.Qualification, proof.Delegation, roots, productionBinaryExpectation(binary.Receipt(), expected), now); err != nil {
		return trust.Envelope{}, err
	}
	var receipt BinaryUpdateReceipt
	if err := protocol.DecodeStrict(envelope.Payload, &receipt, trust.MaxPayloadBytes); err != nil {
		return trust.Envelope{}, err
	}
	receipt.Production = &proof
	payload, err := trust.EncodePayload(receipt)
	if err != nil {
		return trust.Envelope{}, err
	}
	signed, err := trust.Sign(payload, envelope.Scope, envelope.IssuedAt, envelope.ExpiresAt, private)
	if err != nil {
		return trust.Envelope{}, err
	}
	wire, err = trust.EncodeEnvelope(signed)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := VerifyQualifiedBinaryUpdateCurrent(wire, delegationWire, roots, expected, now); err != nil {
		return trust.Envelope{}, err
	}
	return signed, nil
}

type functionFixture struct {
	claim      FunctionClaim
	module     []byte
	root       ed25519.PublicKey
	leaf       ed25519.PrivateKey
	roots      trust.Keyring
	delegation trust.Envelope
	now        time.Time
}

func newFunctionFixture(t *testing.T) functionFixture {
	t.Helper()
	module, err := hex.DecodeString("0061736d0100000001040160000003020100070a01065f737461727400000a040102000b")
	if err != nil {
		t.Fatal(err)
	}
	digest := sha256.Sum256(module)
	claim := FunctionClaim{
		Schema: FunctionSchema, ABI: FunctionABI, TenantID: entityid.Derive("tenant", "function-test"),
		FunctionID: "echo", Revision: "first", Digest: hex.EncodeToString(digest[:]), Bytes: int64(len(module)),
		Capabilities: []string{}, Environment: "canary", Cell: "GRU", Sequence: 42,
	}
	root, rootPrivate, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	leafPublic, leaf, err := ed25519.GenerateKey(rand.Reader)
	if err != nil {
		t.Fatal(err)
	}
	keyID, err := trust.KeyID(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	encodedPublic, err := trust.EncodeDelegatedPublicKey(leafPublic)
	if err != nil {
		t.Fatal(err)
	}
	now := time.Now().UTC().Truncate(time.Second)
	scope := FunctionScope(claim)
	delegation, err := trust.SignDelegation(trust.Delegation{
		SchemaVersion: trust.SchemaVersion, SubjectKeyID: keyID, SubjectPublicKey: encodedPublic,
		Capabilities: []trust.Capability{{Domain: scope.Domain, DeploymentID: scope.DeploymentID, Cell: scope.Cell,
			Environment: scope.Environment, Role: scope.Role, Slots: []string{scope.Slot}, Actions: []string{"sign"}}},
	}, now.Add(-time.Minute), now.Add(2*time.Hour), rootPrivate)
	if err != nil {
		t.Fatal(err)
	}
	roots, err := trust.ParseKeyring(root)
	if err != nil {
		t.Fatal(err)
	}
	return functionFixture{claim: claim, module: module, root: root, leaf: leaf, roots: roots, delegation: delegation, now: now}
}

func (fixture functionFixture) expected() FunctionExpectation {
	claim := fixture.claim
	return FunctionExpectation{Environment: claim.Environment, Cell: claim.Cell, TenantID: claim.TenantID,
		FunctionID: claim.FunctionID, Revision: claim.Revision, Digest: claim.Digest, MinimumSequence: claim.Sequence}
}

func (claim FunctionClaim) Validate() error {
	if claim.Schema != FunctionSchema || claim.ABI != FunctionABI || !entityid.Valid(claim.TenantID) ||
		!serviceRolePattern.MatchString(claim.FunctionID) || !serviceRolePattern.MatchString(claim.Revision) ||
		!digestPattern.MatchString(claim.Digest) || claim.Bytes <= 0 || claim.Bytes > MaxFunctionModuleBytes ||
		len(claim.Capabilities) != 0 || !ValidEnvironment(claim.Environment) || !ValidRegion(claim.Cell) || claim.Sequence == 0 {
		return fmt.Errorf("%w: function ABI, identity, bytes, capabilities or release scope", ErrInvalidReceipt)
	}
	return nil
}

// FunctionScope keeps online signing grants specific to a tenant and function.
func FunctionScope(claim FunctionClaim) trust.Scope {
	return trust.Scope{
		Domain: FunctionDomain, DeploymentID: claim.TenantID, Cell: claim.Cell,
		Environment: claim.Environment, Role: "function-worker", Slot: claim.FunctionID,
	}
}

// SignFunctionClaim signs only bytes matching the claim and a current exact
// root delegation. The producer allocates Sequence durably before calling it.
func SignFunctionClaim(claim FunctionClaim, module []byte, delegation trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if err := claim.validateModule(module); err != nil {
		return trust.Envelope{}, err
	}
	return signReceipt(claim, FunctionScope(claim), delegation, roots, privateKey, now, validFor)
}

// VerifyFunctionCurrent admits portable bytes only after checking the trusted
// roots, exact signing grant, validity, expected identity, sequence and digest.
func VerifyFunctionCurrent(envelopeWire, delegationWire, module []byte, roots trust.Keyring,
	expected FunctionExpectation, now time.Time,
) (VerifiedFunction, error) {
	if err := expected.validate(); err != nil {
		return VerifiedFunction{}, err
	}
	if len(module) == 0 || len(module) > MaxFunctionModuleBytes {
		return VerifiedFunction{}, fmt.Errorf("%w: function module size", ErrInvalidReceipt)
	}
	claim, envelope, err := verifyFunctionReceipt(envelopeWire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedFunction{}, err
	}
	// Retain the copy whose digest is checked, so callers cannot mutate admitted bytes.
	admitted := bytes.Clone(module)
	if err := claim.validateModule(admitted); err != nil {
		return VerifiedFunction{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedFunction{}, err
	}
	return VerifiedFunction{claim: claim, module: admitted, envelope: bytes.Clone(envelopeWire),
		delegation: bytes.Clone(delegationWire), proof: proof}, nil
}

func (claim FunctionClaim) validateModule(module []byte) error {
	if err := claim.Validate(); err != nil {
		return err
	}
	if int64(len(module)) != claim.Bytes {
		return fmt.Errorf("%w: function module size mismatch", ErrInvalidReceipt)
	}
	digest := sha256.Sum256(module)
	if hex.EncodeToString(digest[:]) != claim.Digest {
		return fmt.Errorf("%w: function module digest mismatch", ErrInvalidReceipt)
	}
	return nil
}

// Valid rejects both forged zero values and authority that expired after admission.
func (verified VerifiedFunction) Valid() bool {
	return verified.proof.verified && time.Now().Before(verified.proof.expiresAt)
}

func (verified VerifiedFunction) Claim() FunctionClaim {
	claim := verified.claim
	claim.Capabilities = slices.Clone(claim.Capabilities)
	return claim
}

func (verified VerifiedFunction) Module() []byte         { return bytes.Clone(verified.module) }
func (verified VerifiedFunction) Envelope() []byte       { return bytes.Clone(verified.envelope) }
func (verified VerifiedFunction) Delegation() []byte     { return bytes.Clone(verified.delegation) }
func (verified VerifiedFunction) ExpiresAt() time.Time   { return verified.proof.expiresAt }
func (verified VerifiedFunction) EnvelopeSHA256() string { return verified.proof.envelopeSHA256 }

// VerifyFunctionReceiptCurrent checks the exact expected scope and durable floor
// without loading or authenticating the module bytes named by the receipt.
func VerifyFunctionReceiptCurrent(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected FunctionExpectation, now time.Time,
) (VerifiedFunctionReceipt, error) {
	if err := expected.validate(); err != nil {
		return VerifiedFunctionReceipt{}, err
	}
	claim, envelope, err := verifyFunctionReceipt(envelopeWire, delegationWire, roots, expected, now)
	if err != nil {
		return VerifiedFunctionReceipt{}, err
	}
	proof, err := proofFor(envelope)
	if err != nil {
		return VerifiedFunctionReceipt{}, err
	}
	return VerifiedFunctionReceipt{claim: claim, proof: proof}, nil
}

func (expected FunctionExpectation) validate() error {
	if !ValidEnvironment(expected.Environment) || !ValidRegion(expected.Cell) || !entityid.Valid(expected.TenantID) ||
		!serviceRolePattern.MatchString(expected.FunctionID) || !serviceRolePattern.MatchString(expected.Revision) ||
		!digestPattern.MatchString(expected.Digest) || expected.MinimumSequence == 0 {
		return fmt.Errorf("%w: invalid function expectation or missing durable sequence floor", ErrExpectationMismatch)
	}
	return nil
}

func verifyFunctionReceipt(envelopeWire, delegationWire []byte, roots trust.Keyring,
	expected FunctionExpectation, now time.Time,
) (FunctionClaim, trust.Envelope, error) {
	envelope, delegationEnvelope, err := decodeEnvelopePair(envelopeWire, delegationWire)
	if err != nil {
		return FunctionClaim{}, trust.Envelope{}, err
	}
	claim, err := decodeCanonicalPayload[FunctionClaim](envelope.Payload)
	if err != nil {
		return FunctionClaim{}, trust.Envelope{}, err
	}
	if err := claim.Validate(); err != nil {
		return FunctionClaim{}, trust.Envelope{}, err
	}
	if claim.Environment != expected.Environment || claim.Cell != expected.Cell || claim.TenantID != expected.TenantID ||
		claim.FunctionID != expected.FunctionID || claim.Revision != expected.Revision || claim.Digest != expected.Digest ||
		claim.Sequence < expected.MinimumSequence {
		return FunctionClaim{}, trust.Envelope{}, ErrExpectationMismatch
	}
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return FunctionClaim{}, trust.Envelope{}, fmt.Errorf("verify current function delegation: %w", err)
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, FunctionScope(claim), delegation, now, receiptPolicy()); err != nil {
		return FunctionClaim{}, trust.Envelope{}, fmt.Errorf("verify current function claim: %w", err)
	}
	return claim, envelope, nil
}

func (verified VerifiedFunctionReceipt) Claim() FunctionClaim {
	claim := verified.claim
	claim.Capabilities = slices.Clone(claim.Capabilities)
	return claim
}

func (verified VerifiedFunctionReceipt) Valid() bool {
	return verified.proof.verified && time.Now().Before(verified.proof.expiresAt)
}

func (verified VerifiedFunctionReceipt) ExpiresAt() time.Time   { return verified.proof.expiresAt }
func (verified VerifiedFunctionReceipt) EnvelopeSHA256() string { return verified.proof.envelopeSHA256 }

func signDirect(t *testing.T, payload any, scope trust.Scope, privateKey ed25519.PrivateKey, issuedAt, expiresAt time.Time) trust.Envelope {
	t.Helper()
	encoded, err := trust.EncodePayload(payload)
	if err != nil {
		t.Fatal(err)
	}
	envelope, err := trust.Sign(encoded, scope, issuedAt, expiresAt, privateKey)
	if err != nil {
		t.Fatal(err)
	}
	return envelope
}

func encodeEnvelope(t *testing.T, envelope trust.Envelope) []byte {
	t.Helper()
	encoded, err := trust.EncodeEnvelope(envelope)
	if err != nil {
		t.Fatal(err)
	}
	return encoded
}

func fingerprintWire(t *testing.T, encoded []byte) string {
	t.Helper()
	digest := sha256.Sum256(encoded)
	return hex.EncodeToString(digest[:])
}

func signReceipt(payload any, scope trust.Scope, delegationEnvelope trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if validFor <= 0 || validFor > MaxReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("receipt validity must be positive and no longer than %s", MaxReceiptLifetime)
	}
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return trust.Envelope{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	expiresAt := now.Add(validFor)
	if delegationEnvelope.ExpiresAt.Before(expiresAt) {
		expiresAt = delegationEnvelope.ExpiresAt
	}
	if !expiresAt.After(now) {
		return trust.Envelope{}, trust.ErrExpired
	}
	encodedPayload, err := trust.EncodePayload(payload)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelope, err := trust.Sign(encodedPayload, scope, now, expiresAt, privateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return trust.Envelope{}, fmt.Errorf("release signer is not delegated for this exact scope: %w", err)
	}
	return envelope, nil
}

func decodeEnvelopePair(envelopeWire, delegationWire []byte) (trust.Envelope, trust.Envelope, error) {
	envelope, err := trust.DecodeEnvelope(envelopeWire)
	if err != nil {
		return trust.Envelope{}, trust.Envelope{}, err
	}
	delegation, err := trust.DecodeEnvelope(delegationWire)
	if err != nil {
		return trust.Envelope{}, trust.Envelope{}, fmt.Errorf("decode release delegation: %w", err)
	}
	return envelope, delegation, nil
}

func decodeCanonicalPayload[T any](encoded []byte) (T, error) {
	var value T
	if len(encoded) == 0 || len(encoded) > trust.MaxPayloadBytes {
		return value, fmt.Errorf("%w: receipt payload size", ErrInvalidReceipt)
	}
	if err := protocol.DecodeStrict(encoded, &value, trust.MaxPayloadBytes); err != nil {
		return value, fmt.Errorf("decode release receipt payload: %w", err)
	}
	canonical, err := trust.EncodePayload(value)
	if err != nil {
		return value, err
	}
	if !bytes.Equal(canonical, encoded) {
		return value, fmt.Errorf("%w: payload is not canonical JSON", ErrInvalidReceipt)
	}
	return value, nil
}

func proofFor(envelope trust.Envelope) (receiptProof, error) {
	fingerprint, err := trust.Fingerprint(envelope)
	if err != nil {
		return receiptProof{}, err
	}
	if !digestPattern.MatchString(fingerprint) {
		return receiptProof{}, fmt.Errorf("%w: canonical envelope fingerprint", ErrInvalidReceipt)
	}
	return receiptProof{
		envelopeSHA256: fingerprint, keyID: envelope.KeyID,
		issuedAt: envelope.IssuedAt, expiresAt: envelope.ExpiresAt, verified: true,
	}, nil
}

func delegationPolicy() trust.Policy {
	return trust.Policy{MaxLifetime: MaxDelegationLifetime, ClockSkew: clockSkew}
}

func receiptPolicy() trust.Policy {
	return trust.Policy{MaxLifetime: MaxReceiptLifetime, ClockSkew: clockSkew}
}

func (c VerifiedContainer) Claim() ContainerClaim {
	claim := c.claim
	claim.Production.Qualification = slices.Clone(claim.Production.Qualification)
	claim.Production.Delegation = slices.Clone(claim.Production.Delegation)
	return claim
}
func (c VerifiedContainer) BundleSHA256() string    { return c.bundleSHA256 }
func (c VerifiedContainer) Fingerprint() string     { return c.fingerprint }
func (c VerifiedContainer) ReleaseIdentity() string { return c.identity }
func (c VerifiedContainer) ExpiresAt() time.Time    { return c.expiresAt }
func (c VerifiedContainer) Valid(now time.Time) bool {
	return !now.IsZero() && c.fingerprint != "" && !now.Before(c.issuedAt) && now.Before(c.expiresAt)
}

// ContentManifestDigest remains stable when independent qualification is renewed.
func (claim ContainerClaim) ContentManifestDigest() (string, error) {
	claim.ReleaseSequence = 0
	claim.SequenceMigrationSHA256 = ""
	claim.Production = ProductionProof{}
	wire, err := trust.EncodePayload(claim)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("%x", sha256.Sum256(wire)), nil
}
func (c VerifiedContainer) Migration() SequenceMigration {
	m := c.migration
	m.Regions = slices.Clone(m.Regions)
	return m
}
func (c VerifiedContainer) MigrationEnvelope() trust.Envelope {
	e := c.migrationEnvelope
	e.Payload = slices.Clone(e.Payload)
	return e
}

func ContainerScope(target ContainerTarget) trust.Scope {
	return trust.Scope{Domain: ContainerClaimDomain, DeploymentID: entityid.Derive("container-release", target.Role, target.Environment), Cell: target.Cell, Environment: target.Environment, Role: target.Role, Slot: "linux-" + target.Architecture}
}

func (claim ContainerClaim) Validate() error {
	repository, err := url.Parse(claim.SourceRepository)
	if err != nil || repository.Scheme != "https" || repository.Host == "" || repository.User != nil || repository.RawQuery != "" || repository.Fragment != "" || len(claim.SourceRepository) > 512 || !digestPattern.MatchString(claim.SourceTreeSHA256) {
		return errors.New("container release source requires HTTPS repository and exact SHA-256 tree")
	}

	if claim.Schema != ContainerClaimSchema || !ValidSourceRevision(claim.SourceRevision) || !ValidRegion(claim.Cell) || !ValidEnvironment(claim.Environment) || !serviceRolePattern.MatchString(claim.Role) || claim.Architecture != "arm64" && claim.Architecture != "amd64" || claim.ReleaseSequence == 0 || !digestPattern.MatchString(claim.SequenceMigrationSHA256) || !digestPattern.MatchString(claim.QualificationSHA256) {
		return errors.New("invalid OCI container release claim")
	}
	ref, err := reference.ParseNormalizedNamed(claim.Image)
	if err != nil {
		return fmt.Errorf("invalid container image: %w", err)
	}
	digest, ok := ref.(reference.Canonical)
	if !ok || ref.String() != claim.Image || digest.Digest().Algorithm().String() != "sha256" || digest.Digest().Validate() != nil {
		return errors.New("container release requires canonical sha256 child image reference")
	}
	if _, tagged := ref.(reference.Tagged); tagged {
		return errors.New("container release image must not carry a mutable tag")
	}
	return nil
}

func VerifyContainerCurrent(ctx context.Context, bundle ContainerBundle, roots trust.Keyring, expected ContainerTarget, now, validUntil time.Time, evidence func(context.Context, string) (io.ReadCloser, error), allocations SequenceLocation) (VerifiedContainer, error) {
	if now.IsZero() || validUntil.Before(now) || !ValidRegion(expected.Cell) || !ValidEnvironment(expected.Environment) || !serviceRolePattern.MatchString(expected.Role) || expected.Architecture != "arm64" && expected.Architecture != "amd64" || evidence == nil {
		return VerifiedContainer{}, errors.New("container verification requires admitted target, current time, deadline and evidence store")
	}
	envelope, err := trust.DecodeEnvelope(bundle.Claim)
	if err != nil {
		return VerifiedContainer{}, err
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	verify := func(at time.Time) ([]byte, error) {
		if len(bundle.Delegation) == 0 {
			return trust.VerifyCurrent(envelope, ContainerScope(expected), roots, at, policy)
		}
		grant, err := trust.DecodeEnvelope(bundle.Delegation)
		if err != nil {
			return nil, err
		}
		delegation, err := trust.VerifyDelegationCurrent(grant, roots, at, policy)
		if err != nil {
			return nil, err
		}
		return trust.VerifyDelegatedCurrent(envelope, ContainerScope(expected), delegation, at, policy)
	}
	payload, err := verify(now)
	if err != nil {
		return VerifiedContainer{}, err
	}
	if _, err := verify(validUntil); err != nil {
		return VerifiedContainer{}, err
	}
	verified, err := verifyContainerIdentity(bundle, roots, expected, envelope, payload)
	if err != nil {
		return VerifiedContainer{}, err
	}
	verified.familyEvidence, err = allocations.readWorkerFamily(ctx, roots, verified)
	if err != nil {
		return VerifiedContainer{}, err
	}
	claim := verified.claim
	_, imageDigest, _ := strings.Cut(claim.Image, "@sha256:")
	candidate := ProductionExpectation{SourceRevision: claim.SourceRevision, ArtifactSHA256: imageDigest, QualificationSHA256: claim.QualificationSHA256, Cell: expected.Cell, Environment: expected.Environment, Runtime: ProductionRuntime, Architecture: expected.Architecture, Role: expected.Role}
	proof, err := VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, candidate, now)
	if err != nil {
		return VerifiedContainer{}, err
	}
	if _, err := VerifyProductionCurrent(claim.Production.Qualification, claim.Production.Delegation, roots, candidate, validUntil); err != nil {
		return VerifiedContainer{}, err
	}
	for _, retained := range proof.Evidence {
		reader, err := evidence(ctx, retained.SHA256)
		if err != nil {
			return VerifiedContainer{}, fmt.Errorf("read qualification evidence: %w", err)
		}
		if reader == nil {
			return VerifiedContainer{}, errors.New("qualification evidence store returned no reader")
		}
		hash := sha256.New()
		n, readErr := io.Copy(hash, io.LimitReader(reader, retained.Bytes+1))
		closeErr := reader.Close()
		if err := errors.Join(readErr, closeErr); err != nil {
			return VerifiedContainer{}, err
		}
		if n != retained.Bytes || fmt.Sprintf("%x", hash.Sum(nil)) != retained.SHA256 {
			return VerifiedContainer{}, errors.New("container qualification evidence bytes differ from signed proof")
		}
	}
	qualificationEnvelope, err := trust.DecodeEnvelope(claim.Production.Qualification)
	if err != nil {
		return VerifiedContainer{}, err
	}
	verified.issuedAt = envelope.IssuedAt
	if qualificationEnvelope.IssuedAt.After(verified.issuedAt) {
		verified.issuedAt = qualificationEnvelope.IssuedAt
	}
	verified.expiresAt = validUntil
	for _, expires := range []time.Time{envelope.ExpiresAt, qualificationEnvelope.ExpiresAt} {
		if expires.Before(verified.expiresAt) {
			verified.expiresAt = expires
		}
	}
	return verified, nil
}

// HistoricalContainer authenticates retained ordering evidence without granting runtime authority.
type HistoricalContainer struct{ value VerifiedContainer }

func (c HistoricalContainer) Claim() ContainerClaim   { return c.value.Claim() }
func (c HistoricalContainer) Fingerprint() string     { return c.value.Fingerprint() }
func (c HistoricalContainer) ReleaseIdentity() string { return c.value.ReleaseIdentity() }

// VerifyContainerHistorical authenticates an immutable channel floor, including expired
// release/delegation intervals. Runtime consumers must use VerifyContainerCurrent.
func VerifyContainerHistorical(bundle ContainerBundle, roots trust.Keyring, expected ContainerTarget) (HistoricalContainer, error) {
	envelope, err := trust.DecodeEnvelope(bundle.Claim)
	if err != nil {
		return HistoricalContainer{}, err
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(bundle.Delegation) == 0 {
		payload, err = trust.VerifyHistorical(envelope, ContainerScope(expected), roots, policy)
	} else {
		grant, decodeErr := trust.DecodeEnvelope(bundle.Delegation)
		if decodeErr != nil {
			return HistoricalContainer{}, decodeErr
		}
		delegation, verifyErr := trust.VerifyDelegationHistorical(grant, roots, policy)
		if verifyErr != nil {
			return HistoricalContainer{}, verifyErr
		}
		payload, err = trust.VerifyDelegatedHistorical(envelope, ContainerScope(expected), delegation, policy)
	}
	if err != nil {
		return HistoricalContainer{}, err
	}
	verified, err := verifyContainerIdentity(bundle, roots, expected, envelope, payload)
	if err != nil {
		return HistoricalContainer{}, err
	}
	return HistoricalContainer{value: verified}, nil
}

func verifyContainerIdentity(bundle ContainerBundle, roots trust.Keyring, expected ContainerTarget, envelope trust.Envelope, payload []byte) (VerifiedContainer, error) {
	if !ValidRegion(expected.Cell) || !ValidEnvironment(expected.Environment) || !serviceRolePattern.MatchString(expected.Role) || expected.Architecture != "arm64" && expected.Architecture != "amd64" {
		return VerifiedContainer{}, errors.New("container verification requires admitted target")
	}
	var claim ContainerClaim
	if err := protocol.DecodeStrict(payload, &claim, trust.MaxPayloadBytes); err != nil {
		return VerifiedContainer{}, err
	}
	if err := claim.Validate(); err != nil {
		return VerifiedContainer{}, err
	}
	if err := verifyContainerIndex(bundle.Index, claim); err != nil {
		return VerifiedContainer{}, err
	}
	if claim.Cell != expected.Cell || claim.Environment != expected.Environment || claim.Role != expected.Role || claim.Architecture != expected.Architecture {
		return VerifiedContainer{}, trust.ErrScopeMismatch
	}
	migrationEnvelope, err := trust.DecodeEnvelope(bundle.Migration)
	if err != nil {
		return VerifiedContainer{}, err
	}
	migration, err := VerifySequenceMigrationHistorical(migrationEnvelope, roots, expected.Role, expected.Environment)
	if err != nil {
		return VerifiedContainer{}, err
	}
	migrationDigest, err := trust.Fingerprint(migrationEnvelope)
	if err != nil {
		return VerifiedContainer{}, err
	}
	if claim.ReleaseSequence <= migration.SequenceFloor || claim.SequenceMigrationSHA256 != migrationDigest || envelope.KeyID != migration.SignerKeyID {
		return VerifiedContainer{}, errors.New("container release differs from root-authorized sequence signer or migration")
	}
	if err := verifyWorkerFamilyEvidence(bundle.Sequence, roots, claim); err != nil {
		return VerifiedContainer{}, err
	}
	fingerprint, err := trust.Fingerprint(envelope)
	if err != nil {
		return VerifiedContainer{}, err
	}
	content, err := claim.ContentManifestDigest()
	if err != nil {
		return VerifiedContainer{}, err
	}
	bundleDigest, err := ContainerBundleSHA256(bundle)
	if err != nil {
		return VerifiedContainer{}, err
	}
	identity := fmt.Sprintf("%x", sha256.Sum256([]byte(content+"/"+claim.SequenceMigrationSHA256)))
	return VerifiedContainer{claim: claim, bundleSHA256: bundleDigest, familyEvidence: slices.Clone(bundle.Sequence), migration: migration, migrationEnvelope: migrationEnvelope, fingerprint: fingerprint, identity: identity}, nil
}

// ContainerBundleSHA256 identifies the complete retained bundle, including
// delegation renewals whose signed claim fingerprint remains unchanged.
func ContainerBundleSHA256(bundle ContainerBundle) (string, error) {
	wire, err := protocol.EncodeJSON(bundle)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("%x", sha256.Sum256(wire)), nil
}

const MaxWorkerFamilyEvidenceBytes = 8 << 10

// WorkerFamilyDigest binds the common source and OCI root independently of
// which regions or architectures happen to qualify in this submission.
func (claim ContainerClaim) WorkerFamilyDigest() (string, error) {
	family := struct {
		Schema              string `json:"schema"`
		Role                string `json:"role"`
		Environment         string `json:"environment"`
		SourceRepository    string `json:"source_repository"`
		SourceRevision      string `json:"source_revision"`
		SourceTreeSHA256    string `json:"source_tree_sha256"`
		QualificationSHA256 string `json:"qualification_sha256"`
	}{"terrascale.release.worker-family.v1", claim.Role, claim.Environment, claim.SourceRepository, claim.SourceRevision, claim.SourceTreeSHA256, claim.QualificationSHA256}
	wire, err := trust.EncodePayload(family)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("%x", sha256.Sum256(wire)), nil
}

// WorkerFamilyEvidence returns the authenticated allocation record suitable for
// an immutable same-sequence family pin before a per-architecture floor moves.
func (c VerifiedContainer) WorkerFamilyEvidence() ([]byte, error) {
	if c.fingerprint == "" || len(c.familyEvidence) == 0 {
		return nil, errors.New("worker family requires a verified container")
	}
	return slices.Clone(c.familyEvidence), nil
}

// VerifyWorkerFamilyEvidence authenticates historical allocation evidence and
// compares its family with an already verified incoming worker. It grants no
// runtime authority and never treats another architecture's sequence as a floor.
func VerifyWorkerFamilyEvidence(wire []byte, roots trust.Keyring, incoming VerifiedContainer) error {
	if incoming.fingerprint == "" || len(incoming.familyEvidence) == 0 {
		return errors.New("worker family requires a verified incoming container")
	}
	return verifyWorkerFamilyEvidence(wire, roots, incoming.claim)
}

func verifyWorkerFamilyEvidence(wire []byte, roots trust.Keyring, claim ContainerClaim) error {
	if len(wire) == 0 || len(wire) > MaxWorkerFamilyEvidenceBytes {
		return errors.New("worker family evidence exceeds bound or is missing")
	}
	head, err := verifySequenceHead(wire, roots, claim.Role, claim.Environment)
	if err != nil {
		return err
	}
	migration, err := trust.Fingerprint(head.Migration)
	if err != nil {
		return err
	}
	family, err := claim.WorkerFamilyDigest()
	if err != nil {
		return err
	}
	expected := SequenceIdentity{Role: claim.Role, Environment: claim.Environment, SourceRevision: claim.SourceRevision, ManifestSHA256: family}
	if head.Sequence != claim.ReleaseSequence || head.Identity != expected || migration != claim.SequenceMigrationSHA256 {
		return errors.New("worker differs from authenticated sequence family")
	}
	return nil
}

// readWorkerFamily reads the immutable global winner, never the advancing head.
func (location SequenceLocation) readWorkerFamily(ctx context.Context, roots trust.Keyring, verified VerifiedContainer) ([]byte, error) {
	migration := verified.migration
	if location.Client == nil || location.Namespace != migration.Namespace || location.Bucket != migration.Bucket {
		return nil, errors.New("worker family reader differs from root-authorized sequence location")
	}
	claim := verified.claim
	name := SequenceReservationObject(claim.Role, claim.Environment, claim.SequenceMigrationSHA256, claim.ReleaseSequence)
	response, err := ociclient.ReadObject(ctx, location.Client, objectstorage.GetObjectRequest{NamespaceName: &location.Namespace, BucketName: &location.Bucket, ObjectName: &name})
	if err != nil {
		return nil, err
	}
	if response.Content == nil {
		return nil, errors.New("worker family allocation has no body")
	}
	defer response.Content.Close()
	wire, err := io.ReadAll(io.LimitReader(response.Content, MaxWorkerFamilyEvidenceBytes+1))
	if err != nil {
		return nil, err
	}
	if err := verifyWorkerFamilyEvidence(wire, roots, claim); err != nil {
		return nil, err
	}
	return wire, nil
}

const MaxContainerIndexBytes = 16 << 10

func verifyContainerIndex(wire []byte, claim ContainerClaim) error {
	_, child, _ := strings.Cut(claim.Image, "@sha256:")
	if claim.QualificationSHA256 == child && len(wire) == 0 {
		return nil
	}
	if len(wire) == 0 || len(wire) > MaxContainerIndexBytes || fmt.Sprintf("%x", sha256.Sum256(wire)) != claim.QualificationSHA256 {
		return errors.New("container qualification requires exact bounded retained OCI index bytes")
	}
	var index ocispec.Index
	if err := json.Unmarshal(wire, &index); err != nil || index.SchemaVersion != 2 || index.MediaType != "" && index.MediaType != ocispec.MediaTypeImageIndex && index.MediaType != "application/vnd.docker.distribution.manifest.list.v2+json" || index.ArtifactType != "" || index.Subject != nil || len(index.Manifests) == 0 || len(index.Manifests) > 512 {
		return errors.New("container qualification root is not a standard OCI platform index")
	}
	matches := 0
	for _, descriptor := range index.Manifests {
		platform := descriptor.Platform
		if platform == nil || platform.OS != "linux" || platform.Architecture != claim.Architecture {
			continue
		}
		matches++
		if descriptor.Digest.String() != "sha256:"+child || descriptor.Digest.Validate() != nil || descriptor.Size <= 0 || descriptor.Size > 8<<20 || descriptor.MediaType != ocispec.MediaTypeImageManifest && descriptor.MediaType != "application/vnd.docker.distribution.manifest.v2+json" || len(descriptor.URLs) != 0 || len(descriptor.Data) != 0 || descriptor.ArtifactType != "" || platform.Variant != "" && !(claim.Architecture == "arm64" && platform.Variant == "v8") || platform.OSVersion != "" || len(platform.OSFeatures) != 0 {
			return errors.New("retained OCI index does not bind the exact native child image")
		}
	}
	if matches != 1 {
		return errors.New("retained OCI index requires one matching Linux architecture child")
	}
	return nil
}

func (migration SequenceMigration) Validate() error {
	if migration.Schema != SequenceMigrationSchema || migration.Namespace == "" || len(migration.Namespace) > 128 || migration.Bucket != "gru-1-head" || migration.Region != "GRU" || !sequenceRole.MatchString(migration.Role) || validateEnvironment(migration.Environment) != nil || migration.SequenceFloor == 0 || len(migration.Regions) != 3 {
		return fmt.Errorf("%w: sequence migration scope or regional floors", ErrInvalidReceipt)
	}
	public, err := base64.RawURLEncoding.Strict().DecodeString(migration.SignerPublicKey)
	if err != nil || len(public) != ed25519.PublicKeySize {
		return fmt.Errorf("%w: sequence signer", ErrInvalidReceipt)
	}
	keyID, err := trust.KeyID(ed25519.PublicKey(public))
	if err != nil || keyID != migration.SignerKeyID {
		return trust.ErrKeyMismatch
	}
	seen := make(map[string]bool, 3)
	for _, floor := range migration.Regions {
		if !ValidRegion(floor.Cell) || seen[floor.Cell] || floor.RunNumber < 0 || uint64(floor.RunNumber) > migration.SequenceFloor || !digestPattern.MatchString(floor.EvidenceSHA256) || (floor.RunNumber == 0 && floor.IssuedAt.IsZero()) || (!floor.IssuedAt.IsZero() && floor.IssuedAt.Location() != time.UTC) {
			return fmt.Errorf("%w: sequence migration regional floor", ErrInvalidReceipt)
		}
		seen[floor.Cell] = true
	}
	return nil
}

func SequenceMigrationScope(role, environment string) trust.Scope {
	return trust.Scope{Domain: SequenceMigrationDomain, DeploymentID: entityid.Derive("release-sequence", role, environment), Cell: "global", Environment: environment, Role: role, Slot: "migration"}
}

func SignSequenceMigration(migration SequenceMigration, now time.Time, root ed25519.PrivateKey) (trust.Envelope, error) {
	if err := migration.Validate(); err != nil {
		return trust.Envelope{}, err
	}
	if len(root) != ed25519.PrivateKeySize {
		return trust.Envelope{}, trust.ErrInvalid
	}
	rootID, err := trust.KeyID(root.Public().(ed25519.PublicKey))
	if err != nil {
		return trust.Envelope{}, err
	}
	if rootID == migration.SignerKeyID {
		return trust.Envelope{}, fmt.Errorf("%w: online sequence signer must differ from offline root", ErrInvalidReceipt)
	}
	payload, err := trust.EncodePayload(migration)
	if err != nil {
		return trust.Envelope{}, err
	}
	return trust.Sign(payload, SequenceMigrationScope(migration.Role, migration.Environment), now, now.Add(MaxSequenceMigrationLifetime), root)
}

// VerifySequenceMigrationHistorical checks a durable authorization already
// imported by the signer; importing a new migration requires current validity.
func VerifySequenceMigrationHistorical(envelope trust.Envelope, roots trust.Keyring, role, environment string) (SequenceMigration, error) {
	return verifySequenceMigration(envelope, roots, role, environment, time.Time{})
}

func VerifySequenceMigrationCurrent(envelope trust.Envelope, roots trust.Keyring, role, environment string, now time.Time) (SequenceMigration, error) {
	if now.IsZero() {
		return SequenceMigration{}, fmt.Errorf("%w: migration verification time", ErrInvalidReceipt)
	}
	return verifySequenceMigration(envelope, roots, role, environment, now)
}

func verifySequenceMigration(envelope trust.Envelope, roots trust.Keyring, role, environment string, now time.Time) (SequenceMigration, error) {
	scope := SequenceMigrationScope(role, environment)
	policy := trust.Policy{MaxLifetime: MaxSequenceMigrationLifetime}
	var payload []byte
	var err error
	if now.IsZero() {
		payload, err = trust.VerifyHistorical(envelope, scope, roots, policy)
	} else {
		payload, err = trust.VerifyCurrent(envelope, scope, roots, now, policy)
	}
	if err != nil {
		return SequenceMigration{}, err
	}
	migration, err := decodeCanonicalPayload[SequenceMigration](payload)
	if err != nil {
		return SequenceMigration{}, err
	}
	if err := migration.Validate(); err != nil {
		return SequenceMigration{}, err
	}
	if roots[migration.SignerKeyID] != nil {
		return SequenceMigration{}, fmt.Errorf("%w: sequence signer is an offline root", ErrInvalidReceipt)
	}
	if migration.Role != role || migration.Environment != environment {
		return SequenceMigration{}, trust.ErrScopeMismatch
	}
	return migration, nil
}

func verifySequenceHead(wire []byte, roots trust.Keyring, role, environment string) (sequenceHead, error) {
	var head sequenceHead
	if err := protocol.DecodeStrict(wire, &head, trust.MaxEnvelopeBytes); err != nil {
		return head, err
	}
	migration, err := VerifySequenceMigrationHistorical(head.Migration, roots, role, environment)
	if err != nil {
		return head, err
	}
	if head.Schema != "terrascale.release.sequence.v1" || head.Sequence < migration.SequenceFloor {
		return head, fmt.Errorf("%w: sequence head", ErrInvalidReceipt)
	}
	if head.Identity != (SequenceIdentity{}) {
		if err := head.Identity.validate(); err != nil {
			return head, err
		}
		if head.Identity.Role != role || head.Identity.Environment != environment || head.Sequence == migration.SequenceFloor {
			return head, fmt.Errorf("%w: sequence identity scope", ErrInvalidReceipt)
		}
	} else if head.Sequence != migration.SequenceFloor {
		return head, fmt.Errorf("%w: missing sequence identity", ErrInvalidReceipt)
	}
	if head.Identity != (SequenceIdentity{}) {
		public, _ := base64.RawURLEncoding.Strict().DecodeString(migration.SignerPublicKey)
		payload, err := trust.VerifyHistorical(head.Reservation, sequenceReservationScope(role, environment), trust.Keyring{migration.SignerKeyID: ed25519.PublicKey(public)}, trust.Policy{MaxLifetime: MaxReceiptLifetime})
		if err != nil {
			return head, err
		}
		reservation, err := decodeCanonicalPayload[sequenceReservation](payload)
		if err != nil {
			return head, err
		}
		if reservation.Sequence != head.Sequence || reservation.Identity != head.Identity {
			return head, fmt.Errorf("%w: unauthenticated sequence head", ErrInvalidReceipt)
		}
	}
	return head, nil
}

type sequenceHTTPClient struct{ server *httptest.Server }

func (client sequenceHTTPClient) Do(request *http.Request) (*http.Response, error) {
	cloned := request.Clone(request.Context())
	address := *request.URL
	cloned.URL = &address
	cloned.URL.Scheme = "http"
	cloned.URL.Host = strings.TrimPrefix(client.server.URL, "http://")
	return client.server.Client().Do(cloned)
}

type objectReader interface {
	GetObject(context.Context, objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error)
}

// ReadObject joins SDK retry work while retaining cancellation at the HTTP boundary.
// Other implementations receive the original context and own their cancellation.
func ReadObject(ctx context.Context, client objectReader, request objectstorage.GetObjectRequest) (objectstorage.GetObjectResponse, error) {
	switch sdk := client.(type) {
	case objectstorage.ObjectStorageClient:
		ConfigureReadCancellation(&sdk.BaseClient)
		return sdk.GetObject(ReadContext(ctx), request)
	case *objectstorage.ObjectStorageClient:
		copy := *sdk
		ConfigureReadCancellation(&copy.BaseClient)
		return copy.GetObject(ReadContext(ctx), request)
	default:
		return client.GetObject(ctx, request)
	}
}

