func (verified VerifiedImage) Receipt() ImageReceipt  { return cloneImageReceipt(verified.receipt) }
func (verified VerifiedImage) EnvelopeSHA256() string { return verified.proof.envelopeSHA256 }
func (verified VerifiedImage) KeyID() string          { return verified.proof.keyID }
func (verified VerifiedImage) IssuedAt() time.Time    { return verified.proof.issuedAt }
func (verified VerifiedImage) ExpiresAt() time.Time   { return verified.proof.expiresAt }

func (historical HistoricalImage) IsVerified() bool { return historical.proof.verified }
func (historical HistoricalImage) Receipt() ImageReceipt {
	return cloneImageReceipt(historical.receipt)
}
func (historical HistoricalImage) EnvelopeSHA256() string { return historical.proof.envelopeSHA256 }
func (historical HistoricalImage) KeyID() string          { return historical.proof.keyID }
func (historical HistoricalImage) IssuedAt() time.Time    { return historical.proof.issuedAt }
func (historical HistoricalImage) ExpiresAt() time.Time   { return historical.proof.expiresAt }

// ValidEnvironment reports whether value names a supported release environment.
func ValidEnvironment(value string) bool { return value == "production" || value == "canary" }

// ValidRegion reports whether value is a supported logical region code.
func ValidRegion(value string) bool { return catalog.IsCell(value) }

// ValidOCIImageIDForRegion checks both the image OCID form and logical-region
// mapping used by signed release receipts.
func ValidOCIImageIDForRegion(value, region string) bool {
	if !ValidRegion(region) || !strings.HasPrefix(value, "ocid1.image.") || len(value) > 255 || strings.ContainsAny(value, " \t\r\n") {
		return false
	}
	parts := strings.Split(value, ".")
	return len(parts) == 5 && parts[0] == "ocid1" && parts[1] == "image" && parts[2] == "oc1" &&
		parts[3] == oracleRegion(region) && imageIDPart.MatchString(parts[4])
}

// ValidKernelRelease reports whether value is a bounded, simple kernel release
// token suitable for a signed image receipt.
func ValidKernelRelease(value string) bool { return validKernelRelease(value) }

// ValidSourceRevision reports whether value is a full lowercase Git SHA-1
// revision accepted by binary and image release receipts.
func ValidSourceRevision(value string) bool { return revisionPattern.MatchString(value) }

func signReceipt(payload any, scope trust.Scope, delegationEnvelope trust.Envelope, roots trust.Keyring,
	privateKey ed25519.PrivateKey, now time.Time, validFor time.Duration,
) (trust.Envelope, error) {
	if validFor <= 0 || validFor > MaxReceiptLifetime {
		return trust.Envelope{}, fmt.Errorf("receipt validity must be positive and no longer than %s", MaxReceiptLifetime)
	}
	delegation, err := trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, delegationPolicy())
	if err != nil {
		return trust.Envelope{}, fmt.Errorf("verify current release delegation: %w", err)
	}
	expiresAt := now.Add(validFor)
	if delegationEnvelope.ExpiresAt.Before(expiresAt) {
		expiresAt = delegationEnvelope.ExpiresAt
	}
	if !expiresAt.After(now) {
		return trust.Envelope{}, trust.ErrExpired
	}
	encodedPayload, err := trust.EncodePayload(payload)
	if err != nil {
		return trust.Envelope{}, err
	}
	envelope, err := trust.Sign(encodedPayload, scope, now, expiresAt, privateKey)
	if err != nil {
		return trust.Envelope{}, err
	}
	if _, err := trust.VerifyDelegatedCurrent(envelope, scope, delegation, now, receiptPolicy()); err != nil {
		return trust.Envelope{}, fmt.Errorf("release signer is not delegated for this exact scope: %w", err)
	}
	return envelope, nil
}

func decodeEnvelopePair(envelopeWire, delegationWire []byte) (trust.Envelope, trust.Envelope, error) {
	envelope, err := trust.DecodeEnvelope(envelopeWire)
	if err != nil {
		return trust.Envelope{}, trust.Envelope{}, err
	}
	delegation, err := trust.DecodeEnvelope(delegationWire)
	if err != nil {
		return trust.Envelope{}, trust.Envelope{}, fmt.Errorf("decode release delegation: %w", err)
	}
	return envelope, delegation, nil
}

func decodeCanonicalPayload[T any](encoded []byte) (T, error) {
	var value T
	if len(encoded) == 0 || len(encoded) > trust.MaxPayloadBytes {
		return value, fmt.Errorf("%w: receipt payload size", ErrInvalidReceipt)
	}
	if err := protocol.DecodeStrict(encoded, &value, trust.MaxPayloadBytes); err != nil {
		return value, fmt.Errorf("decode release receipt payload: %w", err)
	}
	canonical, err := trust.EncodePayload(value)
	if err != nil {
		return value, err
	}
	if !bytes.Equal(canonical, encoded) {
		return value, fmt.Errorf("%w: payload is not canonical JSON", ErrInvalidReceipt)
	}
	return value, nil
}

func proofFor(envelope trust.Envelope) (receiptProof, error) {
	fingerprint, err := trust.Fingerprint(envelope)
	if err != nil {
		return receiptProof{}, err
	}
	if !digestPattern.MatchString(fingerprint) {
		return receiptProof{}, fmt.Errorf("%w: canonical envelope fingerprint", ErrInvalidReceipt)
	}
	return receiptProof{
		envelopeSHA256: fingerprint, keyID: envelope.KeyID,
		issuedAt: envelope.IssuedAt, expiresAt: envelope.ExpiresAt, verified: true,
	}, nil
}

func delegationPolicy() trust.Policy {
	return trust.Policy{MaxLifetime: MaxDelegationLifetime, ClockSkew: clockSkew}
}

func receiptPolicy() trust.Policy {
	return trust.Policy{MaxLifetime: MaxReceiptLifetime, ClockSkew: clockSkew}
}

func validateEnvironment(environment string) error {
	if !ValidEnvironment(environment) {
		return fmt.Errorf("%w: unsupported environment", ErrInvalidReceipt)
	}
	return nil
}

func validateImageExpectation(expected ImageExpectation) error {
	if err := validateEnvironment(expected.Environment); err != nil {
		return err
	}
	if !ValidRegion(expected.LogicalRegion) {
		return fmt.Errorf("%w: unsupported logical image region", ErrInvalidReceipt)
	}
	if expected.OCIImageOCID != "" && !ValidOCIImageIDForRegion(expected.OCIImageOCID, expected.LogicalRegion) {
		return fmt.Errorf("%w: expected image OCID is invalid for logical region", ErrExpectationMismatch)
	}
	if expected.Architecture != "" && expected.Architecture != "amd64" && expected.Architecture != "arm64" {
		return fmt.Errorf("%w: expected image architecture is not a receipt architecture", ErrExpectationMismatch)
	}
	return nil
}

func matchImageExpectation(receipt ImageReceipt, expected ImageExpectation) error {
	if receipt.OCIRegion != expected.LogicalRegion || expected.OCIImageOCID != "" && receipt.OCIImageOCID != expected.OCIImageOCID ||
		expected.Architecture != "" && receipt.Architecture != expected.Architecture {
		return ErrExpectationMismatch
	}
	return nil
}

func verifyImageProduction(receipt ImageReceipt, environment string, roots trust.Keyring, now time.Time) (time.Time, error) {
	if receipt.Production == nil {
		return time.Time{}, fmt.Errorf("%w: signed image contains no independent qualification", ErrProductionQualification)
	}
	expected := ProductionExpectation{SourceRevision: receipt.SourceRevision, ArtifactSHA256: receipt.ImageSHA256,
		QualificationSHA256: receipt.QualificationSHA256, Cell: receipt.OCIRegion, Environment: environment,
		Runtime: ProductionRuntime, Architecture: receipt.Architecture, Role: "orchestrator"}
	if _, err := VerifyProductionCurrent(receipt.Production.Qualification, receipt.Production.Delegation, roots, expected, now); err != nil {
		return time.Time{}, err
	}
	envelope, err := trust.DecodeEnvelope(receipt.Production.Qualification)
	if err != nil {
		return time.Time{}, err
	}
	expires := envelope.ExpiresAt
	if len(receipt.Production.Delegation) > 0 {
		delegation, err := trust.DecodeEnvelope(receipt.Production.Delegation)
		if err != nil {
			return time.Time{}, err
		}
		if delegation.ExpiresAt.Before(expires) {
			expires = delegation.ExpiresAt
		}
	}
	return expires, nil
}

func cloneImageReceipt(receipt ImageReceipt) ImageReceipt {
	if receipt.Production != nil {
		receipt.Production = &ProductionProof{Qualification: bytes.Clone(receipt.Production.Qualification),
			Delegation: bytes.Clone(receipt.Production.Delegation)}
	}
	if receipt.HostProduction != nil {
		proofs := make(map[string]ProductionProof, len(receipt.HostProduction))
		for role, proof := range receipt.HostProduction {
			proofs[role] = ProductionProof{Qualification: bytes.Clone(proof.Qualification), Delegation: bytes.Clone(proof.Delegation)}
		}
		receipt.HostProduction = proofs
	}
	return receipt
}

const (
	ProductionQualificationDomain       = "terrascale.release.production-qualification"
	ProductionQualificationSchema       = "terrascale.release.production-qualification.v1"
	FoundationWriterQualificationSchema = "terrascale.release.production-qualification.v2"
	FoundationWriterRole                = "foundation-writer"
	RootCredentialBoundaryGate          = "root-credential-boundary"
	ProductionRuntime                   = "swarmkit-containerd"
	NetBirdProductionRuntime            = "netbird-containerd"
	MaxProductionEvidenceBytes          = 64 << 20
)

var ErrProductionQualification = errors.New("production qualification is missing or invalid")

// ProductionExpectation comes from inspected candidate bytes and the target's scope.
// Build provenance alone never establishes runtime or workload qualification.
type ProductionExpectation struct {
	ImageOCID           string `json:"image_ocid,omitempty"`
	SourceRevision      string `json:"source_revision"`
	ArtifactSHA256      string `json:"artifact_sha256"`
	QualificationSHA256 string `json:"qualification_sha256"`
	Cell                string `json:"cell"`
	Environment         string `json:"environment"`
	Runtime             string `json:"runtime"`
	Architecture        string `json:"architecture"`
	Role                string `json:"role"`
}

type ProductionGateEvidence struct {
	Gate        string    `json:"gate"`
	SHA256      string    `json:"sha256"`
	Bytes       int64     `json:"bytes"`
	CompletedAt time.Time `json:"completed_at"`
}

// ProductionQualification is a separate authority's statement that the required
// gates passed, bound to retained evidence bytes and one exact regional candidate.
type ProductionQualification struct {
	Schema    string                   `json:"schema"`
	Candidate ProductionExpectation    `json:"candidate"`
	Evidence  []ProductionGateEvidence `json:"evidence"`
}

func ProductionQualificationScope(candidate ProductionExpectation) trust.Scope {
	return trust.Scope{Domain: ProductionQualificationDomain, DeploymentID: entityid.Derive("build", candidate.SourceRevision),
		Cell: candidate.Cell, Environment: candidate.Environment, Role: candidate.Role,
		Slot: candidate.Runtime + "/linux-" + candidate.Architecture}
}

// VerifyProductionCurrent accepts a trusted root or an explicitly delegated
// qualification signer. An ordinary binary-release delegation grants no authority.
// The caller must also verify the referenced retained evidence bytes.
func VerifyProductionCurrent(wire, delegationWire []byte, roots trust.Keyring, expected ProductionExpectation, now time.Time) (ProductionQualification, error) {
	var qualification ProductionQualification
	gates := []string{"runtime-ha", "workload-safety"}
	schema := ProductionQualificationSchema
	if expected.Role == FoundationWriterRole {
		schema = FoundationWriterQualificationSchema
		gates = append(gates, RootCredentialBoundaryGate)
	}
	validRuntime := expected.Runtime == ProductionRuntime
	if expected.Role == FoundationWriterRole {
		validRuntime = validRuntime && ValidOCIImageIDForRegion(expected.ImageOCID, expected.Cell)
	}
	if expected.Role == "netbird-manager" || expected.Runtime == NetBirdProductionRuntime {
		validRuntime = expected.Role == "netbird-manager" && expected.Runtime == NetBirdProductionRuntime &&
			expected.Cell == "GRU" && expected.Architecture == "arm64"
		gates = []string{"netbird-foundation", "netbird-recovery"}
	}
	if !ValidSourceRevision(expected.SourceRevision) || !digestPattern.MatchString(expected.ArtifactSHA256) ||
		!digestPattern.MatchString(expected.QualificationSHA256) || !ValidRegion(expected.Cell) ||
		!ValidEnvironment(expected.Environment) || !validRuntime ||
		expected.Architecture != "amd64" && expected.Architecture != "arm64" || !serviceRolePattern.MatchString(expected.Role) {
		return qualification, fmt.Errorf("%w: candidate scope", ErrProductionQualification)
	}
	envelope, err := trust.DecodeEnvelope(wire)
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	policy := trust.Policy{MaxLifetime: MaxUpdateReceiptLifetime}
	var payload []byte
	if len(delegationWire) == 0 {
		payload, err = trust.VerifyCurrent(envelope, ProductionQualificationScope(expected), roots, now, policy)
	} else {
		var delegationEnvelope trust.Envelope
		delegationEnvelope, err = trust.DecodeEnvelope(delegationWire)
		if err == nil {
			var delegation trust.VerifiedDelegation
			delegation, err = trust.VerifyDelegationCurrent(delegationEnvelope, roots, now, policy)
			if err == nil {
				payload, err = trust.VerifyDelegatedCurrent(envelope, ProductionQualificationScope(expected), delegation, now, policy)
			}
		}
	}
	if err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if err := protocol.DecodeStrict(payload, &qualification, trust.MaxPayloadBytes); err != nil {
		return qualification, fmt.Errorf("%w: %w", ErrProductionQualification, err)
	}
	if qualification.Schema != schema || qualification.Candidate != expected || len(qualification.Evidence) != len(gates) {
		return qualification, fmt.Errorf("%w: candidate or required gates", ErrProductionQualification)
	}
	for index, gate := range gates {
		evidence := qualification.Evidence[index]
		if evidence.Gate != gate || !digestPattern.MatchString(evidence.SHA256) ||
			evidence.Bytes <= 0 || evidence.Bytes > MaxProductionEvidenceBytes || evidence.CompletedAt.IsZero() ||
			evidence.CompletedAt.After(envelope.IssuedAt) {
			return qualification, fmt.Errorf("%w: %s evidence", ErrProductionQualification, gate)
		}
	}
	return qualification, nil
}
